<script setup lang="ts">
import { onMounted, onUnmounted, ref } from 'vue';
import AccountPanel from './components/AccountPanel.vue';
import { useTouchControls } from './input-profile';
type RecordRow={id:number;runId:string;difficulty:string;width:number;height:number;mines:number;elapsedMs:number;completedAt:number;assisted:number};
type Completion={runId:string;elapsedMs:number;assisted:boolean};
type Mode='reveal'|'flag'|'question';
const accountRecords=import.meta.env.VITE_ACCOUNT_RECORDS==='true';
const frame=ref<HTMLIFrameElement>(),boardArea=ref<HTMLDivElement>(),recordDialog=ref<HTMLDialogElement>();
const frameWidth=ref(250),frameHeight=ref(370),ready=ref(false),difficulty=ref(0),inputMode=ref<Mode>('reveal');
const touchControls=ref(false);
let mediaQueries:MediaQueryList[]=[];
const message=ref(''),retry=ref<Completion|null>(null),saving=ref(false),records=ref<RecordRow[]>([]),loading=ref(false),total=ref(0),nextBefore=ref<number|null>(null),recordError=ref('');
const levels:Record<string,string>={beginner:'初级',intermediate:'中级',expert:'高级',custom:'自定义',screen:'满屏'};
const modes:{id:Mode;name:string;icon:string;hint:string}[]=[{id:'reveal',name:'翻开',icon:'↖',hint:'点击方块，翻开安全区域'},{id:'flag',name:'插旗',icon:'⚑',hint:'点击插旗，再点一次清除'},{id:'question',name:'问号',icon:'?',hint:'标记不确定的方块，再点清除'}];
const starts=new Map<string,Promise<boolean>>();let requestVersion=0,configured=false;
class ApiError extends Error {constructor(message:string,public status:number){super(message);}}
async function api(url:string,options:RequestInit={}){const response=await fetch(url,{...options,signal:AbortSignal.timeout(10000)});const body=await response.json();if(!response.ok)throw new ApiError(body.error||'请求失败',response.status);return body;}
function control(type:string,value?:unknown){frame.value?.contentWindow?.postMessage({channel:'boardgame:minesweeper:control',type,value},location.origin);}
function configure(){touchControls.value=useTouchControls(window.innerWidth,matchMedia('(pointer:coarse)').matches,matchMedia('(hover:hover)').matches);if(!ready.value)return;control('records-enabled',accountRecords);control('profile',touchControls.value?'touch':'desktop');control('viewport',{width:boardArea.value?.clientWidth||window.innerWidth-32,height:Math.max(300,window.innerHeight-230),scale:touchControls.value?2:1.5});}
function changeMode(mode:Mode){inputMode.value=mode;control('mode',mode);}
async function loadRecords(more=false){
  if(more&&loading.value)return;const version=++requestVersion;loading.value=true;recordError.value='';
  if(!more){records.value=[];total.value=0;nextBefore.value=null;}
  try{const data=await api('/api/me/minesweeper/records'+(more&&nextBefore.value?`?before=${nextBefore.value}`:''));if(version!==requestVersion)return;records.value=more?[...records.value,...data.records]:data.records;total.value=data.total;nextBefore.value=data.nextBefore;}
  catch(err){if(version!==requestVersion)return;records.value=[];total.value=0;nextBefore.value=null;recordError.value=err instanceof ApiError&&err.status===401?'登录后，就能在这里找到你的每一次通关。':'暂时没能加载记录，请重试。';}
  finally{if(version===requestVersion)loading.value=false;}
}
function openRecords(){recordDialog.value?.showModal();void loadRecords();}
async function save(data:Completion){saving.value=true;try{await api(`/api/me/minesweeper/runs/${data.runId}/complete`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({elapsedMs:data.elapsedMs,assisted:data.assisted})});retry.value=null;message.value='通关成功 · 已保存到我的记录';if(recordDialog.value?.open)await loadRecords();}catch{retry.value=data;message.value='通关成功，但记录尚未保存。请保持本局账号并重试。';}finally{saving.value=false;}}
async function receive(event:MessageEvent){
  if(event.origin!==location.origin||event.source!==frame.value?.contentWindow||event.data?.channel!=='boardgame:minesweeper')return;
  const {type,data}=event.data;
  if(type==='layout'&&data&&Number.isFinite(data.width)&&Number.isFinite(data.height)){
    frameWidth.value=Math.max(150,Math.min(5000,data.width));frameHeight.value=Math.max(150,Math.min(3500,data.height));ready.value=true;
    if(Number.isInteger(data.difficulty))difficulty.value=data.difficulty;
    if(modes.some(m=>m.id===data.mode))inputMode.value=data.mode;
    if(!configured){configured=true;configure();}return;
  }
  if(type==='records'){if(accountRecords)openRecords();return;}
  if(type!=='layout'&&!accountRecords){if(type==='won')message.value='通关成功！再来一局？';return;}
  if(!data||typeof data.runId!=='string')return;
  if(type==='started'&&!starts.has(data.runId)){
    message.value='';if(starts.size>100)starts.delete(starts.keys().next().value!);
    starts.set(data.runId,api('/api/me/minesweeper/runs',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)}).then(()=>true).catch(()=>false));
  }
  if(type==='won'){if(!await starts.get(data.runId)){message.value='通关啦！登录后新开一局，可以保存通关记录。';return;}await save({runId:data.runId,elapsedMs:data.elapsedMs,assisted:data.assisted});}
}
function accountChanged(){retry.value=null;message.value='账号已切换 · 新开一局即可保存记录';records.value=[];total.value=0;++requestVersion;if(recordDialog.value?.open)void loadRecords();}
onMounted(()=>{document.title='扫雷经典版';mediaQueries=[matchMedia('(pointer:coarse)'),matchMedia('(hover:hover)')];mediaQueries.forEach(q=>q.addEventListener('change',configure));configure();window.addEventListener('message',receive);window.addEventListener('resize',configure);window.addEventListener('boardgame:account-changed',accountChanged);});
onUnmounted(()=>{mediaQueries.forEach(q=>q.removeEventListener('change',configure));window.removeEventListener('message',receive);window.removeEventListener('resize',configure);window.removeEventListener('boardgame:account-changed',accountChanged);});
</script>
<template>
  <main class="sweeper-page">
    <header class="play-header"><span class="back">CLASSIC</span><h1><span aria-hidden="true">✹</span> 扫雷 <small>经典版</small></h1><div class="account"><AccountPanel v-if="accountRecords" compact /><span v-else class="standalone-label">单机版</span></div></header>
    <div class="play-meta"><span class="eyebrow">MINESWEEPER</span><button v-if="accountRecords" class="record-link" @click="openRecords">◷ 我的记录</button></div>
    <nav class="difficulty" aria-label="选择难度"><button v-for="(label,index) in ['初级','中级','高级','自定义','满屏']" :key="label" :disabled="!ready" :aria-pressed="difficulty===index" :class="{selected:difficulty===index}" @click="control('difficulty',index)">{{label}}</button></nav>
    <section class="board-stage" aria-label="扫雷游戏"><div ref="boardArea" class="board-scroll"><iframe ref="frame" src="/classic-minesweeper/index.html?embedded=1" title="经典扫雷棋盘" :style="{width:frameWidth+'px',height:frameHeight+'px'}" scrolling="no" @load="configured=false"></iframe></div></section>
    <section v-if="touchControls" class="input-controls" aria-label="选择点击模式"><p class="mode-label">点击方式 <span>{{modes.find(m=>m.id===inputMode)?.hint}}</span></p><div class="mode-buttons"><button v-for="mode in modes" :key="mode.id" :disabled="!ready" :aria-pressed="inputMode===mode.id" :class="{active:inputMode===mode.id}" @click="changeMode(mode.id)"><span class="mode-icon" aria-hidden="true">{{mode.icon}}</span><span>{{mode.name}}</span><span v-if="inputMode===mode.id" class="mode-check" aria-hidden="true">✓</span></button></div></section>
    <div class="play-footer"><button class="new-game" :disabled="!ready" @click="control('new')">↻ 重新开始</button><span>点数字展开周围 · 插错旗会踩雷</span></div>
    <p v-if="message" class="notice" role="status">{{message}} <button v-if="retry" :disabled="saving" @click="save(retry!)">{{saving?'保存中':'重试保存'}}</button><button class="dismiss" aria-label="关闭提示" @click="message=''">×</button></p>
    <details class="instructions"><summary>怎么玩？</summary><p>电脑：左键翻开，右键循环标记；点击已翻开的数字展开周围。手机：先选“翻开 / 插旗 / 问号”，再点格子，同一标记再点可清除。</p><p>数字表示周围八格的地雷数。插旗后还需点击数字，旗数吻合才展开相邻未标记方块；插错旗会踩雷，旗数不足或过多不会展开。点击表情可以重新开局。</p></details>
    <dialog v-if="accountRecords" ref="recordDialog" class="records-dialog" aria-labelledby="records-title"><div class="dialog-heading"><div><p class="eyebrow">JUST YOUR GAMES</p><h2 id="records-title">我的通关记录 <small v-if="total">{{total}} 次</small></h2></div><button class="close-dialog" aria-label="关闭通关记录" @click="recordDialog?.close()">×</button></div><p v-if="loading&&!records.length" class="empty">正在找回你的记录…</p><div v-else-if="recordError" class="empty"><span class="empty-icon" aria-hidden="true">◷</span><p>{{recordError}}</p></div><div v-else-if="!records.length" class="empty"><span class="empty-icon" aria-hidden="true">⚑</span><p>第一场胜利，值得被记住。</p><small>登录后开始游戏，通关会自动保存。</small></div><ul v-else class="record-list"><li v-for="record in records" :key="record.runId"><div><strong>{{levels[record.difficulty]}} <span v-if="record.assisted" class="assisted">辅助</span></strong><p>{{record.width}} × {{record.height}} · {{record.mines}} 雷</p><time>{{new Date(record.completedAt).toLocaleString()}}</time></div><span class="record-time">{{(record.elapsedMs/1000).toFixed(1)}}<small> 秒</small></span></li></ul><button v-if="nextBefore" class="load-more" :disabled="loading" @click="loadRecords(true)">加载更多</button><div class="record-bottom"><button :disabled="loading" @click="loadRecords()">刷新</button><details><summary>记录说明</summary><p>登录后新开的游戏才能关联账号。个人单机记录由客户端上报；使用彩蛋或停表会标注“辅助”，不计入正式联机战绩。</p></details></div></dialog>
  </main>
</template>
<style scoped>
