buttons button.active{color:#fff;background:#355e45;border-color:#355e45;box-shadow:0 3px 7px #2d51381c}.mode-icon{font-family:serif;font-size:21px;line-height:1}.mode-check{position:absolute;right:8px;top:6px;font-size:9px;opacity:.7}.play-footer{max-width:440px;margin:17px auto 0;display:flex;gap:10px;justify-content:space-between;align-items:center}.play-footer>span{font-size:10px;color:#98a08f}.new-game{font-size:11px;color:#75876f;background:transparent;border:0;cursor:pointer;padding:7px 0}.instructions{max-width:440px;margin:22px auto 0;border-top:1px solid #e0e5d8;padding-top:13px;font-size:11px;color:#8e9883}.instructions summary{cursor:pointer;width:max-content}.instructions p{line-height:1.9;font-size:11px;color:#7c8874}.notice{position:relative;margin:18px auto 0;max-width:480px;padding:12px 33px 12px 14px;border:1px solid #d6dfcd;border-radius:7px;font-size:12px;line-height:1.8;background:#f0f3e9;color:#496047}.notice button:not(.dismiss){border:0;background:none;color:#2e5f3c;text-decoration:underline;cursor:pointer}.dismiss{position:absolute;right:7px;top:7px;border:0;background:none;font-size:18px;color:#8d9a82;cursor:pointer}.records-dialog{width:min(520px,calc(100vw - 28px));max-height:82dvh;box-sizing:border-box;padding:27px;border:1px solid #e0e4d8;border-radius:14px;background:#fafbf5;color:#293f32;box-shadow:0 22px 100px #10251338}.records-dialog::backdrop{background:#17291f66;backdrop-filter:blur(3px)}.dialog-heading{display:flex;align-items:center;justify-content:space-between;gap:12px}.dialog-heading h2{font-size:22px;margin:8px 0 0}.dialog-heading h2 small{font-size:12px;font-weight:400;color:#89957e}.close-dialog{align-self:start;background:none;border:0;padding:0 4px;font-size:24px;color:#8b987f;cursor:pointer}.empty{text-align:center;padding:42px 8px;color:#7d8e72;font-size:13px}.empty-icon{font-size:32px;color:#b4c1a8}.empty p{margin:15px 0 8px}.empty small{font-size:11px;color:#a0aa95}.record-list{list-style:none;padding:0;margin:20px 0}.record-list li{display:flex;align-items:center;justify-content:space-between;padding:16px 0;border-bottom:1px solid #e1e6d8;gap:10px}.record-list strong{font-size:14px}.record-list p{font-size:11px;color:#85947a;margin:6px 0}.record-list time{font-size:10px;color:#a0aa94}.record-time{font-size:24px;color:#3e6045;font-variant-numeric:tabular-nums;white-space:nowrap}.record-time small{font-size:11px;color:#91a081}.assisted{font-size:9px;font-weight:400;padding:2px 5px;background:#e8ecde;color:#899973;border-radius:3px}.record-bottom{display:flex;gap:16px;align-items:start;justify-content:space-between;font-size:10px;color:#9aa58e;border-top:1px solid #e2e7d9;padding-top:14px}.record-bottom button{background:none;border:0;color:#6b805e;cursor:pointer;font-size:11px}.record-bottom details{max-width:300px}.record-bottom summary{cursor:pointer;text-align:right}.record-bottom p{line-height:1.8;font-size:11px}.load-more{display:block;margin:15px auto;border:1px solid #cdd8bf;background:none;color:#658056;border-radius:5px;padding:8px 18px;cursor:pointer}button:disabled{opacity:.5;cursor:wait}button:focus-visible,a:focus-visible,summary:focus-visible{outline:2px solid #608a50;outline-offset:4px}@media(max-width:600px){.sweeper-page{padding:0 14px 20px}.play-header{height:62px;gap:5px}.play-header h1{font-size:18px}.play-header h1 small{display:none}.back{font-size:12px}.play-meta{margin:17px 0 12px}.difficulty{gap:2px}.difficulty button{min-width:55px;padding:8px 10px;font-size:12px}.board-stage{margin:20px 0}.mode-buttons button{min-height:52px;font-size:14px}.play-footer{align-items:start}.play-footer>span{max-width:160px;line-height:1.7;text-align:right}.records-dialog{padding:22px}.instructions{margin-top:17px}.mode-label>span{font-size:9px}.account{font-size:11px}}
